from itertools import permutations

def is_balanced(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    if not lst:
        return 'No'

    str1, str2 = lst[0], lst[1]

    if not str1 and not str2:
        return 'Yes'

    if str1.count('(') != str1.count(')') or str2.count('(') != str2.count(')'):
        return 'No'

    perms = permutations([str1, str2])

    for perm in perms:
        concat_str = ''.join(perm)
        if is_balanced(concat_str):
            return 'Yes'

    return 'No'

